const crypto = require('crypto');
const input = $json.body ?? $json;
const headers = $json.headers ?? {};
const timestamp = String(headers['x-codebell-timestamp'] || headers['X-Codebell-Timestamp'] || '');
const signature = String(headers['x-codebell-signature'] || headers['X-Codebell-Signature'] || '');
const eventId = String(headers['x-codebell-event-id'] || input.event_id || '');
const secret = $env.CB_N8N_SIGNING_SECRET;
if (!secret) throw new Error('CB_N8N_SIGNING_SECRET is not configured');
if (!timestamp || Math.abs(Date.now() - Number(timestamp)) > 300000) throw new Error('Expired event');
const raw = JSON.stringify(input);
const expected = crypto.createHmac('sha256', secret).update(`${timestamp}.${raw}`).digest('hex');
if (!signature || signature.length !== expected.length || !crypto.timingSafeEqual(Buffer.from(signature, 'hex'), Buffer.from(expected, 'hex'))) throw new Error('Invalid signature');
if (input.event_type !== 'lead.created' || input.event_version !== 1 || !eventId || input.payload?.brand_id !== 'codebell_development') throw new Error('Invalid event schema');
const data = $getWorkflowStaticData('global');
data.processedEvents = data.processedEvents || {};
const duplicate = Boolean(data.processedEvents[eventId]);
if (!duplicate) data.processedEvents[eventId] = new Date().toISOString();
return [{ json: { ...input, duplicate } }];

const payload = $json.payload;
const assigned = Boolean(payload.assigned_to);
return [{ json: { ...$json, assignment: assigned ? 'assigned' : 'unassigned_queue', notification_configured: Boolean($env.CB_NOTIFICATION_WEBHOOK_URL), notification: { lead_reference: payload.lead_reference, service: payload.service, submission_time: $json.occurred_at, crm_url: `${$env.CB_CRM_BASE_URL || 'https://www.codebell.online'}${payload.crm_path}`, assigned_owner: payload.assigned_to || 'unassigned_queue' } } }];
